mapper.select:
/* CastExecutionMapper.retrieveSaveDt */
SELECT TO_CHAR(MAX(SAVE_DT), 'YYYYMMDDHH24MISS') FROM PMOWN.TN_PM_SMLT_CURRENT_SAVE
WHERE OWNER_USER_ID = #{loginUserId} AND EXCN_YMD = #{ymd} AND TMNL_ID = #{fcltTmnlId}

/* CastExecutionMapper.hasSaved */
SELECT COUNT(*) FROM PMOWN.TN_PM_SMLT_CURRENT_SAVE
WHERE OWNER_USER_ID = #{scope.loginUserId} AND EXCN_YMD = #{scope.ymd} AND TMNL_ID = #{scope.fcltTmnlId} AND AREA_CD = #{area}

/* CastExecutionMapper.retrieveInputBase */
SELECT B.* FROM PMOWN.TN_PM_SMLT_INPUT_BASE B
WHERE #{ymd} BETWEEN B.VALID_BGN_YMD AND B.VALID_END_YMD AND B.USE_YN = 'Y'

mapper.insert:
/* CastExecutionMapper.archiveInput */
INSERT INTO PMOWN.TN_PM_SMLT_INPUT_SNAPSHOT (SMLT_ID, RESOURCE_TYPE, RESOURCE_ID, SOURCE_ID, PAYLOAD)
VALUES (#{smltId}, #{type}, #{resourceId}, #{sourceId}, #{payload,jdbcType=CLOB})
